window.HOEREN_TESTS[57] = {"id":"beim-friseur-und-beauty","name":"Beim Friseur und Beauty","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Kunden: Unser Friseur-Salon hat ab Mai neue Preise. Damen-Haarschnitt 35 Euro statt 30. Herren-Haarschnitt 25 Euro statt 22. Färben 70 Euro statt 65. 45 Euro kostet nur das Verwöhn-Paket mit Massage, der normale Schnitt bleibt bei 35. Wir entschuldigen uns für die Erhöhung — gestiegene Kosten. Vielen Dank für Ihr Verständnis!","gender":"f","q":"Was kostet ein Damen-Haarschnitt jetzt?","opts":["35 Euro.","45 Euro.","30 Euro."],"correct":0},{"transcript":"Hallo Anna, hier ist Lisa. Hör mal, ich habe Termin beim Friseur am Mittwoch — möchtest du auch? Können zusammen gehen. Färben lassen, ich nehme rot. Nur schneiden wäre mir zu wenig, und nichts machen kommt nicht in Frage. Du wolltest doch was Neues? Bei Maria im Salon, Maxstraße 10. Ruf zurück, bis dann!","gender":"f","q":"Was möchte Lisa machen?","opts":["Haare schneiden.","Nichts.","Haare färben."],"correct":2},{"transcript":"Achtung Kunden: Unsere Friseurin Petra ist krank diese Woche. Sie ist nicht im Urlaub und hat nicht gekündigt, sie ist wirklich krank. Termine bei ihr werden verschoben — wir rufen alle persönlich an. Wer dringend braucht, kann zur Kollegin Sabine — gleiche Qualität, freie Termine vorhanden. Wir entschuldigen uns. Bis bald!","gender":"m","q":"Was ist mit Petra?","opts":["Sie ist im Urlaub.","Sie ist krank.","Sie hat gekündigt."],"correct":1},{"transcript":"Hi Markus, hier ist Tom. Mein erstes Mal beim Friseur seit einem Jahr! Haare sehr lang, fast wie Frau. Habe Termin morgen — kurz schneiden, modern. Lang lassen will ich nicht mehr, und färben auch nicht, nur kurz. Bin nervös, das letzte Mal war schrecklich. Diesmal anderer Friseur. Wünsch mir Glück!","gender":"m","q":"Was möchte Tom?","opts":["Kurz schneiden.","Lange Haare lassen.","Färben."],"correct":0},{"transcript":"Liebe Damen: Im Beauty-Salon Schön bieten wir neue Behandlungen. Massage neu im Programm, Gesichtsbehandlung schon länger. Auch Maniküre und Pediküre. Aktion diese Woche: 20% auf alle Behandlungen außer Massage. Termin online buchen, bitte. Fragen Sie an der Rezeption nach Details. Wir freuen uns auf euch!","gender":"f","q":"Was ist nicht im Angebot?","opts":["Gesichtsbehandlung.","Maniküre.","Massage."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer macht was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lukas","gender":"m","text":"Hallo Lisa! Der Salon hat morgen früh noch zwei Plätze frei."},{"speaker":"Lisa","gender":"f","text":"Schön, dass du fragst. Ich will vor der Feier noch gepflegt aussehen."},{"speaker":"Lukas","gender":"m","text":"Ich lasse mich rasieren. Der Bart kratzt mich schon seit einer Woche."},{"speaker":"Lisa","gender":"f","text":"Ich nehme eine Maniküre. Meine Nägel sollen zum Kleid passen."},{"speaker":"Lukas","gender":"m","text":"Will jemand heute die Haare färben?"},{"speaker":"Lisa","gender":"f","text":"Nein. Haare färben will hier niemand."},{"speaker":"Lukas","gender":"m","text":"Tom hat nach dem Sport einen richtig steifen Rücken."},{"speaker":"Lisa","gender":"f","text":"Tom bekommt eine Massage. Eine Stunde auf der Liege lockert seinen Rücken."},{"speaker":"Lukas","gender":"m","text":"Sara hat trockene Haut in diesem Winter."},{"speaker":"Lisa","gender":"f","text":"Sara wählt eine Gesichtsbehandlung. Die Creme hilft ihr schon nach kurzer Zeit."},{"speaker":"Lukas","gender":"m","text":"Bucht jemand ein Solarium für etwas Farbe?"},{"speaker":"Lisa","gender":"f","text":"Nein. Ein Solarium brauchen wir nicht. Die Sonne reicht uns völlig."},{"speaker":"Lukas","gender":"m","text":"Tim läuft viel und seine Füße tun seit Tagen weh."},{"speaker":"Lisa","gender":"f","text":"Tim meldet sich für eine Pediküre an. Danach kann er wieder lange Strecken gehen."},{"speaker":"Lukas","gender":"m","text":"Dann sage ich dem Salon heute noch Bescheid."},{"speaker":"Lisa","gender":"f","text":"Ich komme morgen um neun und habe genug Zeit."}],"options":[{"letter":"a","text":"Massage"},{"letter":"b","text":"Haare färben"},{"letter":"c","text":"Wimpern"},{"letter":"d","text":"Rasieren"},{"letter":"e","text":"Gesichtsbehandlung"},{"letter":"f","text":"Pediküre"},{"letter":"g","text":"Maniküre"},{"letter":"h","text":"Augenbrauen"},{"letter":"i","text":"Solarium"}],"items":[{"person":"Lukas","correct":"d"},{"person":"Lisa","correct":"g"},{"person":"Tom","correct":"a"},{"person":"Sara","correct":"e"},{"person":"Tim","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag! Ich möchte etwas Neues. Aber bitte nicht sehr kurz!"},{"speaker":"Friseurin","gender":"f","text":"Wie wäre es schulterlang? Drei Finger breit über die Schultern?"},{"speaker":"Kundin","gender":"f","text":"Ja, schulterlang ist gut. Mit Pony oder ohne?"},{"speaker":"Friseurin","gender":"f","text":"Mit Pony, aber kurzem Pony. Nur Spitzen schneiden wäre zu wenig."},{"speaker":"Kundin","gender":"f","text":"Gut, schulterlang mit Pony! Wann fangen wir an?"}],"q":"Was möchte die Kundin?","opts":["Schulterlang mit Pony.","Sehr kurz.","Nur Spitzen."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag! Was kostet Bart trimmen, nur Bart allein?"},{"speaker":"Barbier","gender":"m","text":"Zum Haarschnitt dazu 10 Euro extra. Allein kostet es 15 Euro, ganz schnell."},{"speaker":"Kunde","gender":"m","text":"Und mit Rasur zusammen 25 Euro, oder?"},{"speaker":"Barbier","gender":"m","text":"Genau, mit klassischer Rasur 25 Euro. Was darf es heute sein?"},{"speaker":"Kunde","gender":"m","text":"Nur Bart trimmen für 15 Euro, bitte."},{"speaker":"Barbier","gender":"m","text":"Gern! Nehmen Sie Platz, es geht sofort los!"}],"q":"Was kostet nur Bart?","opts":["15 Euro.","10 Euro.","25 Euro."],"correct":0},{"lines":[{"speaker":"Mutter","gender":"f","text":"Klein-Lukas, deine Haare sind zu lang! Wir gehen zum Friseur."},{"speaker":"Lukas","gender":"m","text":"Nein, ich hasse das! Bitte zu Hause selbst schneiden!"},{"speaker":"Mutter","gender":"f","text":"Zu Hause wird es schief. Oder willst du beides, halb hier, halb dort?"},{"speaker":"Lukas","gender":"m","text":"Nein! Entweder zu Hause oder gar nicht!"},{"speaker":"Mutter","gender":"f","text":"Kein Entweder-oder! Wir gehen zum Friseur, danach bekommst du Eis."}],"q":"Wo werden Haare geschnitten?","opts":["Zu Hause.","Beim Friseur.","Beide."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag! Kann ich meinen Termin verschieben? Ich hatte Donnerstag um 15 Uhr."},{"speaker":"Empfang","gender":"f","text":"Wohin denn? Freitag oder Samstag wäre frei."},{"speaker":"Frau","gender":"f","text":"Freitag geht nicht, da arbeite ich lange."},{"speaker":"Empfang","gender":"f","text":"Dann Samstag um 14 Uhr? Da ist noch etwas frei, am Nachmittag."},{"speaker":"Frau","gender":"f","text":"Perfekt, Samstag um 14 Uhr! Vielen Dank und tschüss!"}],"q":"Neuer Termin ist?","opts":["Donnerstag.","Samstag.","Freitag."],"correct":1},{"lines":[{"speaker":"Mann","gender":"m","text":"Hat alles gut geklappt? Der Schnitt ist super! Möchten Sie Trinkgeld? Ich gebe 3 oder 5 Euro?"},{"speaker":"Friseur","gender":"m","text":"Wie Sie möchten, das ist nett! 10 Euro wäre zu viel."},{"speaker":"Mann","gender":"m","text":"Dann 5 Euro Trinkgeld, bitte schön!"},{"speaker":"Friseur","gender":"m","text":"Vielen Dank, sehr nett! Bis zum nächsten Mal!"},{"speaker":"Friseur","gender":"m","text":"Danke schön! Und bis zum nächsten Mal in vier Wochen!"}],"q":"Wie viel Trinkgeld?","opts":["3 Euro.","10 Euro.","5 Euro."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klein, einer Friseurin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klein, Sie arbeiten als Friseurin seit 20 Jahren und haben einen eigenen Salon. Wie sind Sie dazu gekommen?"},{"speaker":"Klein","gender":"f","text":"Als Teenager habe ich Freundinnen die Haare geschnitten — alle haben gesagt, ich habe Talent. Mit 17 Ausbildung in einem kleinen Salon, mit 25 eigene Stelle als Meisterin. Mit 30 eigener Salon. Schon immer mein Traum."},{"speaker":"Reporter","gender":"m","text":"Was sind die Trends heute?"},{"speaker":"Klein","gender":"f","text":"Natürlich aussehen ist groß — keine schreiend bunten Farben mehr. Balayage, Highlights, natürliche Töne. Bei Männern Bärte sind beliebt, aber gepflegt. Lange Haare bei Männern auch wieder im Kommen."},{"speaker":"Reporter","gender":"m","text":"Was sind die häufigsten Fehler von Kunden?"},{"speaker":"Klein","gender":"f","text":"Selbst färben zu Hause — fast immer schief gegangen. Wir müssen dann Reparatur machen, teuer und schwer. Auch Bilder von Promis zeigen — aber Promi hat anderes Gesicht, andere Struktur. Was bei ihr passt, passt bei dir vielleicht nicht."},{"speaker":"Reporter","gender":"m","text":"Wie sehen Sie die Konkurrenz?"},{"speaker":"Klein","gender":"f","text":"Discount-Friseure überall — 10 Euro Haarschnitt. Können wir nicht konkurrieren. Aber wer Qualität will, kommt zu uns. Treue Kunden sind wichtig — manche schon 15 Jahre bei mir. Das macht Spaß."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie jungen Friseuren?"},{"speaker":"Klein","gender":"f","text":"Lernt nicht nur Schneiden — auch Geschäft, Kunden-Service, Mitarbeiter-Führung. Sonst wird man nie Chef. Auch: immer weiterlernen, Trends folgen, neue Techniken. Wer stehen bleibt, verliert. Beruf ist anstrengend, aber kreativ und schön."}],"items":[{"q":"Schreiend bunte Farben sind heute der Hauptrend.","correct":"nein"},{"q":"Frau Klein hat schon als Teenager Haare geschnitten.","correct":"ja"},{"q":"Selbst-Färben zu Hause klappt fast immer gut.","correct":"nein"},{"q":"Sie hat Kunden, die schon 15 Jahre zu ihr kommen.","correct":"ja"},{"q":"Sie rät jungen Friseuren, weiter zu lernen.","correct":"ja"}]}]};
